const BONUS_ICONS={'Champignon':'🍄','Fleur':'🔥','Étoile':'⭐'};
const FACTION_ICONS={'Sabre bleu':'🟦','X-Wing':'🚀','R2D2':'🤖','Sabre rouge':'🟥','TIE Fighter':'🛸','Droïde de combat':'👾'};
const FULL_OPTIONS=['Factory','Abstract Factory','Builder','Prototype','Singleton'];

const state={screen:'home',previousScreen:'home',xp:0,completed:new Set(),trophies:new Set(),mastery:Object.fromEntries(PATTERNS.map(p=>[p.id,0])),runs:{},active:null,calibrationIndex:0,calibrationDone:false,bossIndex:0,bossDone:false,attempts:0,feedback:null,busy:false,dragValue:null,modal:false,epoch:0,workshopVisual:{},bossSolved:0};
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const encode=s=>encodeURIComponent(String(s));
const waitNext=(fn,ms=1500)=>{const e=state.epoch;setTimeout(()=>{if(e!==state.epoch)return;state.busy=false;state.feedback=null;state.attempts=0;fn();render();},ms);};
const addXP=n=>{state.xp+=n;};
const mastery=(id,n)=>{state.mastery[id]=Math.min(100,state.mastery[id]+n);};
function resetTransient(){state.epoch++;state.attempts=0;state.feedback=null;state.busy=false;state.dragValue=null;}
function progressOf(id){const i=PATTERNS.findIndex(p=>p.id===id);return i===0||state.completed.has(PATTERNS[i-1].id);}
function speak(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(speak.timer);speak.timer=setTimeout(()=>el.classList.remove('visible'),2300);}
function sparkle(count=24){const layer=$('#particle-layer');const palette=['#39d7ff','#ad8cff','#ffbf73','#6be7ac','#ff79ac'];for(let i=0;i<count;i++){const node=document.createElement('i');node.className='particle';node.style.left=(18+Math.random()*68)+'%';node.style.top=(20+Math.random()*55)+'%';node.style.setProperty('--dx',(Math.random()*480-240)+'px');node.style.setProperty('--dy',(Math.random()*-320-30)+'px');node.style.setProperty('--rot',(Math.random()*850)+'deg');node.style.background=palette[Math.floor(Math.random()*palette.length)];layer.appendChild(node);setTimeout(()=>node.remove(),1400);}}
function startGame(){resetTransient();state.screen=state.calibrationDone?'map':'calibration';render();}
function openMap(){resetTransient();state.screen='map';render();}
function openHome(){resetTransient();state.screen='home';render();}
function enterWorld(id,restart=false){if(!progressOf(id))return;if(state.busy)return;resetTransient();state.active=id;if(!state.runs[id]||restart){state.runs[id]={phase:'briefing',round:0,quizIndex:0,visual:{made:[],jedi:[],sith:[],ship:{},stealth:false,stealthColor:false,aqua:false,aquaColor:false,aquaGear:false,calls:[]}};}state.screen='world';render();}
function launchBoss(){if(state.completed.size!==5)return;resetTransient();state.bossIndex=0;state.bossSolved=0;state.screen='bossIntro';render();}
function beginWorkshop(){const run=state.runs[state.active];run.phase='workshop';run.round=0;resetTransient();render();}
function beginBoss(){resetTransient();state.screen='boss';render();}
function feedbackHTML(){const f=state.feedback;if(!f)return `<div class="placeholder-feedback">⤴ Glisse une carte vers le récepteur ou clique directement dessus.</div>`;return `<div class="feedback ${f.good?'success':f.rejected?'reveal':'error'}" role="status"><span class="feedback-symbol">${f.good?'✓':f.rejected?'◎':'!'}</span><div><strong>${escapeHTML(f.head)}</strong><p>${escapeHTML(f.body)}</p></div></div>`;}
function grade(value,correct,hint,explanation,onAccept,onNext,points=75,mastId=null,total=1){
 if(state.busy)return;
 if(value===correct){state.busy=true;state.feedback={good:true,head:'SYSTÈME VALIDÉ · +'+points+' XP',body:explanation};addXP(points);if(mastId)mastery(mastId,Math.ceil(45/total));if(onAccept)onAccept();sparkle(15);render();waitNext(onNext,1500);return;}
 state.attempts++;
 if(state.attempts>=3){state.busy=true;state.feedback={rejected:true,head:'CORRECTION AUTOMATIQUE · +15 XP',body:'Réponse attendue : '+correct+'. '+explanation};addXP(15);if(mastId)mastery(mastId,3);if(onAccept)onAccept();render();waitNext(onNext,2700);return;}
 state.feedback={head:'RÉGLAGE INCORRECT · ESSAI '+state.attempts+'/3',body:hint+' Il te reste '+(3-state.attempts)+' essai(s).'};
 render();
}
function resolveCalibration(value){const t=CATEGORY_TASKS[state.calibrationIndex];grade(value,t.answer,t.hint,t.explanation,null,()=>{state.calibrationIndex++;if(state.calibrationIndex>=CATEGORY_TASKS.length){state.calibrationDone=true;state.screen='map';speak('Calibration terminée ! Les ateliers sont accessibles.');sparkle(45);}},40);}
function visualApply(id,t){const v=state.runs[id].visual;if(id==='factory')v.made.push(t.answer);if(id==='abstract')v[t.side.toLowerCase()].push(t.answer);if(id==='builder')v.ship[t.part]=t.answer;if(id==='prototype'){if(t.clone)v[t.clone]=true;if(t.part)v[t.part]=true;}if(id==='singleton')v.calls.push(t.answer);}
function answerWorkshop(value){const id=state.active,run=state.runs[id],list=WORKSHOPS[id],t=list[run.round];grade(value,t.answer,t.hint,t.explanation,()=>visualApply(id,t),()=>{run.round++;if(run.round>=list.length){run.phase='quiz';run.quizIndex=0;speak('Atelier réparé ! Contrôle des connaissances.');}},75,id,list.length);}
function answerQuiz(value){const id=state.active,run=state.runs[id],q=QUIZZES[id][run.quizIndex],expected=q.opts[q.answer];grade(value,expected,q.hint,q.explain,null,()=>{run.quizIndex++;if(run.quizIndex>=QUIZZES[id].length)completeWorld(id);},100,id,3);}
function completeWorld(id){const run=state.runs[id];run.phase='reward';const first=!state.completed.has(id);state.completed.add(id);state.trophies.add(id);if(first){addXP(200);mastery(id,10);}sparkle(62);speak(BY_ID[id].reward+' obtenu !');}
function answerBoss(value){const t=BOSS_ROUNDS[state.bossIndex];grade(value,t.answer,t.hint,t.explain,null,()=>{state.bossIndex++;state.bossSolved++;if(state.bossIndex>=BOSS_ROUNDS.length){state.bossDone=true;state.trophies.add('boss');addXP(500);state.screen='ending';sparkle(85);speak('NULL-7 neutralisé !');}},150);}

function render(){renderHUD();renderNav();renderMastery();const main=$('#main');
 if(state.screen==='home')main.innerHTML=renderHome();
 if(state.screen==='calibration')main.innerHTML=renderCalibration();
 if(state.screen==='map')main.innerHTML=renderMap();
 if(state.screen==='world')main.innerHTML=renderWorld();
 if(state.screen==='bossIntro')main.innerHTML=renderBossIntro();
 if(state.screen==='boss')main.innerHTML=renderBoss();
 if(state.screen==='ending')main.innerHTML=renderEnding();
 renderModal();}
function renderHUD(){$('#hud-xp').textContent=String(state.xp).padStart(4,'0')+' XP';$('#hud-progress').textContent=state.completed.size+' / 5';$('#hud-trophies').textContent=state.trophies.size+' / 6';}
function renderNav(){const nav=$('#world-nav');nav.innerHTML=PATTERNS.map(p=>{const unlocked=progressOf(p.id),done=state.completed.has(p.id),active=state.active===p.id&&state.screen==='world';return `<button class="nav-world ${active?'active':''} ${done?'done':''} ${!unlocked?'locked':''}" data-nav="${p.id}" ${!unlocked?'disabled':''} style="--local:${p.color}"><span class="nav-icon">${unlocked?p.icon:'🔒'}</span><span class="nav-world-copy"><small>ATELIER ${p.number}</small><strong>${escapeHTML(p.name)}</strong></span><span class="nav-check">${done?'✓':unlocked?'›':'·'}</span></button>`;}).join('')+`<button class="nav-world boss-nav ${state.screen.startsWith('boss')?'active':''} ${state.bossDone?'done':''}" data-nav="boss" ${state.completed.size===5?'':'disabled'}><span class="nav-icon">${state.completed.size===5?'👾':'🔒'}</span><span class="nav-world-copy"><small>MISSION FINALE</small><strong>NULL-7</strong></span><span class="nav-check">${state.bossDone?'✓':'›'}</span></button><button class="nav-map" data-nav="map">◉ &nbsp; CARTE DES ATELIERS</button>`;}
function renderMastery(){$('#mastery-panel').innerHTML=PATTERNS.map(p=>`<div class="mastery-item"><div class="mastery-top"><span>${p.icon} ${escapeHTML(p.name)}</span><b>${state.mastery[p.id]}%</b></div><div class="mastery-track"><span style="width:${state.mastery[p.id]}%;background:${p.color}"></span></div></div>`).join('');$('#trophy-panel').innerHTML=[...PATTERNS,{id:'boss',reward:'Architecte légendaire',badge:'🏆'}].map(p=>`<span title="${escapeHTML(p.reward)}" class="trophy ${state.trophies.has(p.id)?'won':''}">${state.trophies.has(p.id)?p.badge:'◇'}</span>`).join('');$('#intel-tip-text').textContent=state.screen==='world'?BY_ID[state.active].when:state.screen==='boss'?'NULL-7 exploite les confusions entre les patrons : étudie le besoin avant de choisir.':'Une bonne architecture commence par le bon problème à résoudre.';}
const stepsMarkup=(done,total,label='UNITÉS RESTAURÉES')=>`<div class="steps-bar"><div class="steps-top"><span>${label}</span><b>${done} / ${total}</b></div><div class="steps-track"><span style="width:${(done/total)*100}%"></span></div></div>`;
const lore=(face,text)=>`<div class="character-message"><span class="portrait">${face}</span><div><strong>MESSAGE DU CONTRÔLE CENTRAL</strong><p>${text}</p></div></div>`;
const action=(text,act,classes='btn-primary')=>`<button class="${classes}" data-action="${act}">${text} <span class="arrow">↗</span></button>`;
function choices(items,icons={},hint='GLISSE OU CLIQUE'){return `<div class="choice-header"><span>◈ ${hint}</span><span class="tiny">CLIC = SÉLECTION · DRAG & DROP = DÉPÔT</span></div><div class="choice-grid">${items.map((s,i)=>`<button class="choice-card" draggable="true" ${state.busy?'disabled':''} data-select="${encode(s)}" title="Sélectionner ${escapeHTML(s)}"><span class="choice-emoji">${icons[s]||['✦','⬡','◈','◉','⚡','◆'][i%6]}</span><span class="choice-label">${escapeHTML(s)}</span><span class="choice-grip">⠿</span></button>`).join('')}</div>`;}
function dropzone(label='DÉPOSER ICI',cls=''){return `<div class="drop-target ${cls}" aria-label="Zone de dépôt"><span class="drop-ring">◎</span><strong>${label}</strong><small>Glisse une pièce ici ou clique sur sa carte</small></div>`;}
function renderHome(){return `<section class="hero entrance">
 <div class="hero-copy"><div class="serial"><span class="pulse-dot"></span> CHAPITRE 01 // ALERTE DE CONCEPTION</div><span class="eyebrow hero-kicker">UNE AVENTURE ARCADE POUR ARCHITECTES EN DEVENIR</span>
 <h1>RÉPARE <em>L'USINE</em><br>DES PATRONS<span class="title-spark">✦</span></h1><p class="hero-lead">L'IA rebelle <strong>NULL-7</strong> a saboté cinq ateliers de création. Répare les machines, manipule les objets et maîtrise les cinq patrons avant l'attaque finale.</p>
 <div class="hero-stats"><div><strong>05</strong><small>ATELIERS</small></div><div><strong>30–40</strong><small>MIN MAX.</small></div><div><strong>100%</strong><small>HORS LIGNE</small></div></div>
 <div class="button-row">${action('DÉMARRER LA MISSION','start')}<button class="btn-outline" data-action="guide">◌ &nbsp; MODE D'EMPLOI</button></div>
 <p class="fineprint">Progression non sauvegardée · Aucun son · Chrome et Edge · Souris ou clavier</p></div>
 <div class="hero-machine" aria-hidden="true"><div class="machine-orbit orbit-1"></div><div class="machine-orbit orbit-2"></div><div class="machine-orbit orbit-3"></div><div class="machine-core"><span>⚙</span><small>DESIGN<br>PATTERNS</small></div><div class="machine-node node-1">🏭</div><div class="machine-node node-2">🌌</div><div class="machine-node node-3">🚀</div><div class="machine-node node-4">🧬</div><div class="machine-node node-5">🔐</div><div class="machine-floor"></div><div class="machine-caption">RÉACTEUR DE CRÉATION // ÉTAT : CRITIQUE</div></div></section>
 <div class="home-extras"><div class="ticker"><span>◉ ALERTE</span><div>PROTOCOLE NULL-7 DÉTECTÉ <i>✦</i> CINQ MACHINES HORS SERVICE <i>✦</i> RÉPARATION PAR PATRONS DE CONCEPTION <i>✦</i> CONNAISSANCES + EXPÉRIMENTATION <i>✦</i></div></div>
 <div class="teaser-grid"><div><strong>01 · OBSERVER</strong><p>Comprends le besoin et expérimente la machine.</p></div><div><strong>02 · CONSTRUIRE</strong><p>Glisse des composants, crée des familles et clone des objets.</p></div><div><strong>03 · MAÎTRISER</strong><p>Réponds aux défis et débloque les trophées.</p></div></div></div>`;}
function renderCalibration(){const idx=state.calibrationIndex,t=CATEGORY_TASKS[idx];return `<section class="mission-head entrance"><div class="mission-path">PROTOCOLE D'ACCÈS <span>›</span> CALIBRAGE</div><div class="eyebrow">// 00 · LES TROIS CATÉGORIES</div><h1>INITIALISATION <span class="accent-cyan">GoF</span></h1><p>Avant d'entrer dans l'usine, reconnais les trois catégories de patrons de conception.</p></section>
 <section class="workbench entrance"><div class="task-pane">${stepsMarkup(idx,3,'CALIBRAGE')}<div class="panel-label">SIGNAL ${String(idx+1).padStart(2,'0')}</div><h2>À quelle catégorie appartient ce besoin ?</h2><div class="story-objective"><span>▸</span><p>${escapeHTML(t.prompt)}</p></div>${choices(CATEGORIES,{'Création':'🏗️','Comportement':'⚡','Structure':'🧩'})}${feedbackHTML()}</div>
 <div class="visual-pane"><div class="device-header"><span>⚙ CLASSIFICATEUR</span><span class="on-air">● ACTIF</span></div><div class="calibration-device"><div class="classifier-center">${['🏗️','⚡','🧩'][idx]}</div><div class="classifier-rays"><span></span><span></span><span></span></div><div class="classifier-readout">ANALYSE DU BESOIN EN COURS...</div></div>${dropzone('RÉCEPTEUR DE CATÉGORIE')}</div></section>`;}
function renderMap(){return `<section class="mission-head entrance"><div class="mission-path">SALLE DE CONTRÔLE <span>›</span> CARTE DES ATELIERS</div><div class="eyebrow">// CARTE OPÉRATIONNELLE</div><h1>CHOISIS TON <span class="accent-cyan">ATELIER</span></h1><p>Répare les systèmes dans l'ordre. Un atelier terminé déverrouille le suivant.</p></section>
 ${lore('🤖',state.completed.size===0?'« Architecte, NULL-7 brouille tous nos plans. Entre dans l’atelier Factory : nos bonus ne sortent plus de l’usine ! »':state.completed.size===5?'« Tous les ateliers sont rétablis. Mais NULL-7 a lancé sa dernière attaque. Active le protocole final ! »':`« Beau travail, architecte ! ${state.completed.size} atelier(s) réparé(s). Continue à récupérer nos plans de construction. »`)}
 <section class="map-grid entrance">${PATTERNS.map((p,i)=>{const unlocked=progressOf(p.id),done=state.completed.has(p.id);return `<button class="map-card ${done?'map-done':''} ${unlocked?'':'map-locked'}" style="--local:${p.color}" data-nav="${p.id}" ${unlocked?'':'disabled'}><span class="map-index">ZONE ${p.number} <span>${done?'✓ TERMINÉ':unlocked?'◉ DISPONIBLE':'🔒 VERROUILLÉ'}</span></span><span class="map-icon">${unlocked?p.icon:'🔒'}</span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.short)}</small><span class="map-card-line"></span><span class="map-card-foot">${done?'REVOIR L’ATELIER':unlocked?'ENTRER DANS L’ATELIER':'TERMINE L’ATELIER PRÉCÉDENT'} &nbsp; ↗</span></button>`;}).join('')}
 <button class="map-card final-map ${state.completed.size===5?'':'map-locked'}" data-nav="boss" ${state.completed.size===5?'':'disabled'}><span class="map-index">ZONE 06 <span>${state.bossDone?'✓ TERMINÉ':state.completed.size===5?'● DISPONIBLE':'🔒 VERROUILLÉ'}</span></span><span class="map-icon">${state.completed.size===5?'👾':'🔒'}</span><strong>BOSS : NULL-7</strong><small>Examen final · décisions d’architecture</small><span class="map-card-line"></span><span class="map-card-foot">${state.completed.size===5?'LANCER LA MISSION FINALE':'RESTAURE LES CINQ ATELIERS'} &nbsp; ↗</span></button></section>`;}
function renderWorld(){const id=state.active,p=BY_ID[id],run=state.runs[id];const stageName={briefing:'BRIEFING',workshop:'SIMULATION',quiz:'VALIDATION',reward:'VICTOIRE'}[run.phase];return `<div class="world-theme" style="--local:${p.color}"><section class="mission-head entrance"><div class="mission-path"><button class="path-back" data-nav="map">← PLAN DE L'USINE</button><span>›</span> ATELIER ${p.number} <span>›</span> ${stageName}</div><div class="eyebrow">// MISSION ${p.number} · PATRON DE CRÉATION</div><h1><span class="world-emoji">${p.icon}</span> ${escapeHTML(p.name.toUpperCase())}</h1><p>${escapeHTML(p.desc)}</p></section>
 ${run.phase==='briefing'?renderBriefing(p):run.phase==='workshop'?renderWorkshop(p,run):run.phase==='quiz'?renderQuiz(p,run):renderReward(p)}</div>`;}
function renderBriefing(p){return `<section class="briefing-card entrance"><div class="brief-spotlight"><span class="brief-circle">${p.icon}</span><span class="brief-serial">MODULE ${p.number} / 05</span><div class="brief-bars"><span></span><span></span><span></span><span></span><span></span></div></div><div class="brief-content"><div class="eyebrow">// NOUVEL OBJECTIF</div><h2>${escapeHTML(p.slogan)}</h2><p class="brief-description">${escapeHTML(p.idea)}</p><div class="brief-points"><div><span>🎯</span><p><b>QUAND L'UTILISER ?</b>${escapeHTML(p.when)}</p></div><div><span>⚠️</span><p><b>PIÈGE À ÉVITER</b>${escapeHTML(p.trap)}</p></div></div><div class="button-row">${action('ENTRER DANS L’ATELIER','workshop')}<button class="btn-outline" data-action="guide">◌ &nbsp; AIDE</button></div></div></section>${lore('🤖',`« Bienvenue dans l’atelier ${p.name}. Répare la machine par manipulation, puis réussis trois défis de compréhension. »`)}`;}
function renderWorkshop(p,run){const list=WORKSHOPS[p.id],t=list[run.round],n=run.round+1;let opts;if(p.id==='factory')opts=['Champignon','Fleur','Étoile'];else if(p.id==='abstract')opts=['Sabre bleu','Sabre rouge','X-Wing','TIE Fighter','R2D2','Droïde de combat'];else if(p.id==='singleton')opts=t.options||['Armurerie','Hangar','Radar'];else opts=t.options;
 const icons=p.id==='factory'?BONUS_ICONS:p.id==='abstract'?FACTION_ICONS:{};
 return `<div class="progress-ribbon"><span><i class="status-light"></i> ATELIER EN COURS</span><strong>MANIPULATION ${n} / ${list.length}</strong><button data-action="help" class="text-help">? RAPPEL THÉORIQUE</button></div>
 <section class="workbench entrance"><div class="task-pane">${stepsMarkup(run.round,list.length,'OPÉRATIONS VALIDÉES')}<div class="panel-label">▸ ORDRE DE FABRICATION ${String(n).padStart(2,'0')}</div><h2>${escapeHTML(t.prompt)}</h2><div class="story-objective"><span>⊙</span><p>${escapeHTML(t.detail)}</p></div>${choices(opts,icons,p.id==='factory'?'CHOISIS LE BON BONUS':p.id==='abstract'?'CHOISIS LE PRODUIT COMPATIBLE':p.id==='singleton'?'ACTIVE LE BON TERMINAL':'SÉLECTIONNE LA PIÈCE OU L’ACTION')}${feedbackHTML()}</div>
 <div class="visual-pane"><div class="device-header"><span>◈ ${escapeHTML(p.slogan)}</span><span class="on-air">● EN LIGNE</span></div>${renderDevice(p.id,run,t)}${dropzone(p.id==='factory'?'TRÉMIE DE PRODUCTION':p.id==='abstract'?'DOCK DE LA FACTION':p.id==='singleton'?'PORT D’ACCÈS AU NOYAU':'STATION D’ASSEMBLAGE')}<div class="device-foot">TRANSMISSION SÉCURISÉE <span>// ${p.number}-0${n} · 100%</span></div></div></section>
 <section class="insight-bar"><strong>💡 À RETENIR</strong><span>${escapeHTML(p.when)}</span></section>`;}
function renderDevice(id,run,t){const v=run.visual;
 if(id==='factory')return `<div class="factory-device device-scene"><div class="factory-heading"><span>INJECTION TYPE</span><strong>BonusFactory</strong></div><div class="factory-engine"><div class="factory-tube tube-left"></div><div class="factory-gear">⚙</div><div class="factory-gear gear-small">⚙</div><div class="factory-smoke">◌</div><div class="factory-tube tube-right"></div><div class="factory-belt"><span></span><span></span><span></span><span></span></div></div><div class="factory-output"><small>OBJETS PRODUITS</small><div>${v.made.length?v.made.map(x=>`<span title="${escapeHTML(x)}">${BONUS_ICONS[x]}</span>`).join(''):'<span class="empty-output">EN ATTENTE...</span>'}</div></div></div>`;
 if(id==='abstract'){const j=v.jedi,s=v.sith;return `<div class="faction-device device-scene"><div class="faction-toggle"><span class="${t.side==='Jedi'?'active-jedi':''}">✧ JEDI</span><span class="${t.side==='Sith'?'active-sith':''}">✦ SITH</span></div><div class="faction-core ${t.side==='Sith'?'darkside':''}"><div class="faction-emblem">${t.side==='Jedi'?'🔵':'🔴'}</div><strong>${t.side}Factory</strong><small>USINE ACTIVE</small></div><div class="families"><div class="family ${t.side==='Jedi'?'highlight':''}"><strong>JEDI</strong>${['Sabre bleu','X-Wing','R2D2'].map(x=>`<span class="${j.includes(x)?'collected':''}">${j.includes(x)?FACTION_ICONS[x]:'◇'}</span>`).join('')}</div><div class="family ${t.side==='Sith'?'highlight':''}"><strong>SITH</strong>${['Sabre rouge','TIE Fighter','Droïde de combat'].map(x=>`<span class="${s.includes(x)?'collected':''}">${s.includes(x)?FACTION_ICONS[x]:'◇'}</span>`).join('')}</div></div></div>`;}
 if(id==='builder')return `<div class="builder-device device-scene"><div class="hangar-grid"></div><div class="ship-construction ${v.ship.carlingue?'has-hull':''} ${v.ship.arme?'has-weapon':''} ${v.ship.bouclier?'has-shield':''} ${v.ship.droïde?'has-droid':''}"><div class="ship-glow"></div><div class="ship-wing wing-top"></div><div class="ship-wing wing-bottom"></div><div class="ship-body"></div><div class="ship-cockpit"></div><div class="ship-cannon cannon-top"></div><div class="ship-cannon cannon-bottom"></div><div class="ship-shield"></div><div class="ship-droid">🤖</div><div class="ship-thruster">➤</div></div><div class="ship-parts">${[['carlingue','CARLINGUE'],['arme','ARME'],['bouclier','BOUCLIER'],['droïde','DROÏDE']].map(([key,label])=>`<span class="${v.ship[key]?'installed':''}">${v.ship[key]?'✓':'·'} ${label}</span>`).join('')}</div></div>`;
 if(id==='prototype'){const armor=(name,cls,detail,active=true)=>`<div class="armor-pod ${cls} ${active?'present':'missing'}"><div class="armor-figure"><div class="armor-head"></div><div class="armor-shoulders"></div><div class="armor-torso"><span></span></div><div class="armor-legs"></div></div><strong>${name}</strong><small>${detail}</small></div>`;return `<div class="prototype-device device-scene"><div class="clone-link"><span>PROTOTYPE</span><span class="clone-arrow">─── ✦ ───</span><span>VARIANTES</span></div><div class="armor-showcase">${armor('MARK 42','armor-red','Rouge et or')}${armor('STEALTH',v.stealthColor?'armor-black':'armor-red',v.stealthColor?'Noir furtif':v.stealth?'En attente de couleur':'Non clonée',v.stealth)}${armor('AQUA',v.aquaColor?'armor-blue':'armor-red',v.aquaGear?'Aquatique équipée':v.aqua?'En construction':'Non clonée',v.aqua)}</div><div class="clone-counter">COPIES DISPONIBLES <strong>${Number(v.stealth)+Number(v.aqua)}</strong></div></div>`;}
 return `<div class="singleton-device device-scene"><div class="jarvis-orbit"><div class="jarvis-ring ring-outer"></div><div class="jarvis-ring ring-inner"></div><div class="jarvis-core"><span>◉</span><strong>J.A.R.V.I.S.</strong></div></div><div class="singleton-readings"><div><small>INSTANCES</small><strong>${v.calls.length?1:0}</strong></div><div><small>ACCÈS</small><strong>${Math.min(v.calls.length,3)}</strong></div></div><div class="terminal-chips">${['Armurerie','Hangar','Radar'].map(x=>`<span class="${v.calls.includes(x)?'online':''}">${v.calls.includes(x)?'●':'○'} ${x}</span>`).join('')}</div></div>`;
}
function renderQuiz(p,run){const q=QUIZZES[p.id][run.quizIndex];return `<div class="progress-ribbon"><span><i class="status-light"></i> MODE VALIDATION</span><strong>QUESTION ${run.quizIndex+1} / 3</strong><button data-action="help" class="text-help">? RAPPEL THÉORIQUE</button></div>
 <section class="quiz-section entrance"><div class="quiz-top"><span class="quiz-icon">◈</span><span>TEST DE MAÎTRISE // ${escapeHTML(p.name.toUpperCase())}</span><span class="quiz-bonus">+100 XP</span></div>${stepsMarkup(run.quizIndex,3,'QUESTIONS RÉUSSIES OU CORRIGÉES')}<div class="quiz-question"><div class="panel-label">QUESTION ${String(run.quizIndex+1).padStart(2,'0')}</div><h2>${escapeHTML(q.q)}</h2></div><div class="answers-grid">${q.opts.map((o,i)=>`<button class="answer-card" data-select="${encode(o)}" ${state.busy?'disabled':''}><span class="answer-letter">${'ABCD'[i]}</span><span>${escapeHTML(o)}</span><span class="answer-arrow">↗</span></button>`).join('')}</div>${feedbackHTML()}<div class="quiz-caption">Tu disposes de trois tentatives par question. Après trois erreurs, la correction est expliquée.</div></section>`;}
function renderReward(p){const i=PATTERNS.findIndex(x=>x.id===p.id),next=PATTERNS[i+1];return `<section class="reward-screen entrance"><div class="win-stars">✦　✧　✦</div><span class="victory-tag">MODULE ${p.number} RESTAURÉ</span><div class="reward-medal">${p.badge}</div><h1>MISSION <em>ACCOMPLIE !</em></h1><p>Tu as réparé l’atelier <strong>${escapeHTML(p.name)}</strong> et récupéré un nouveau plan d’architecture.</p><div class="reward-list"><div><small>NOUVEAU TROPHÉE</small><strong>${escapeHTML(p.reward)}</strong></div><div><small>MAÎTRISE ACTUELLE</small><strong>${state.mastery[p.id]} %</strong></div><div><small>EXPÉRIENCE TOTALE</small><strong>${state.xp} XP</strong></div></div><div class="learning-recap"><strong>📘 MÉMO D'ARCHITECTE</strong><p>${escapeHTML(p.desc)} ${escapeHTML(p.when)}</p><small>ATTENTION : ${escapeHTML(p.trap)}</small></div><div class="button-row center">${next?action('ATELIER SUIVANT · '+next.name,'nextWorld'):action('AFFRONTER NULL-7','final') }<button class="btn-outline" data-nav="map">VOIR LA CARTE</button><button class="btn-outline" data-action="replayWorld">↻ REJOUER</button></div></section>`;}
function renderBossIntro(){return `<section class="boss-intro entrance"><div class="boss-glitch">◢ SIGNAL PIRATE INTERCEPTÉ ◣</div><div class="boss-avatar"><span>👾</span><div class="boss-rings"></div></div><h1>LE PROTOCOLE <em>NULL-7</em></h1><p>« Tu sais construire des objets ? Voyons si tu sais <strong>choisir le bon patron</strong> lorsque les besoins se ressemblent… »</p><div class="boss-dossier"><div><strong>08</strong><small>SCÉNARIOS</small></div><div><strong>05</strong><small>PATRONS</small></div><div><strong>03</strong><small>ESSAIS / DÉFI</small></div></div><p class="boss-note">Niveau plus difficile : distinctions Factory / Abstract Factory, Builder / Prototype et limites de Singleton.</p><div class="button-row center">${action('LANCER LE COMBAT FINAL','beginBoss')}<button class="btn-outline" data-nav="map">RETOUR À L'USINE</button></div></section>`;}
function renderBoss(){const t=BOSS_ROUNDS[state.bossIndex];return `<section class="mission-head entrance boss-heading"><div class="mission-path"><button class="path-back" data-nav="map">← CARTE</button><span>›</span> MISSION FINALE</div><div class="eyebrow">// ALERTE CRITIQUE · NULL-7</div><h1>CHOISIS LE <span class="accent-pink">BON PATRON</span></h1><p>Analyse chaque problème : quel modèle de conception répond le plus précisément au besoin ?</p></section><div class="progress-ribbon red-ribbon"><span>👾 NULL-7 : TEST ${state.bossIndex+1} / ${BOSS_ROUNDS.length}</span><strong>${Math.round((state.bossIndex/BOSS_ROUNDS.length)*100)}% DU VIRUS NEUTRALISÉ</strong></div>
 <section class="workbench boss-workbench entrance"><div class="task-pane">${stepsMarkup(state.bossIndex,BOSS_ROUNDS.length,'VULNÉRABILITÉS CORRIGÉES')}<div class="panel-label">MENACE ${String(state.bossIndex+1).padStart(2,'0')} · ${escapeHTML(t.tag)}</div><h2>${escapeHTML(t.prompt)}</h2>${choices(FULL_OPTIONS,Object.fromEntries(PATTERNS.map(x=>[x.name,x.icon])),'SÉLECTIONNE LE PATRON ADAPTÉ')}${feedbackHTML()}</div><div class="visual-pane"><div class="device-header"><span>◈ TERMINAL ANTI-MALWARE</span><span class="malware-status">● DANGER</span></div><div class="boss-device device-scene"><div class="boss-virus">👾<span class="boss-scanline"></span></div><div class="boss-target"><strong>INTRUSION EN COURS</strong><small>NULL-7 // VIRUS ARCHITECTURAL</small></div><div class="boss-progress-dots">${BOSS_ROUNDS.map((_,i)=>`<i class="${i<state.bossIndex?'destroyed':i===state.bossIndex?'current':''}"></i>`).join('')}</div></div>${dropzone('CONTRE-MESURE UML','boss-drop')}</div></section><section class="insight-bar boss-insight"><strong>⚠️ MÉTHODE</strong><span>Cherche le problème principal, pas seulement les mots du scénario.</span></section>`;}
function renderEnding(){const min=Math.min(...PATTERNS.map(p=>state.mastery[p.id]));return `<section class="ending-screen entrance"><div class="win-stars">✦　✧　✦</div><div class="ending-trophy">🏆</div><div class="victory-tag">USINE INTÉGRALEMENT RÉPARÉE</div><h1>ARCHITECTE <em>DES PATRONS</em></h1><p>NULL-7 est neutralisé. Les cinq ateliers fonctionnent de nouveau, et tu as débloqué les six trophées de l'Académie.</p><div class="end-stats"><div><span>✦</span><strong>${state.xp}</strong><small>XP GAGNÉS</small></div><div><span>◇</span><strong>5 / 5</strong><small>PATRONS TERMINÉS</small></div><div><span>🏆</span><strong>6 / 6</strong><small>TROPHÉES</small></div></div><div class="rank-banner"><span>RANG FINAL</span><strong>${min>=90?'MAÎTRE DES PATRONS':min>=65?'ARCHITECTE CONFIRMÉ':'APPRENTI ARCHITECTE'}</strong></div><p class="ending-tip">Le vrai défi est de reconnaître un problème de conception, puis de choisir une solution adaptée : pas d’appliquer des patrons partout.</p><div class="button-row center"><button class="btn-primary" data-action="restart">↻ &nbsp; RECOMMENCER DE ZÉRO</button><button class="btn-outline" data-nav="map">EXPLORER LES ATELIERS</button></div></section>`;}
const GUIDE_SECTIONS=[
 ['🎮 OBJECTIF','Répare les cinq ateliers dans l’ordre, puis affronte NULL-7. La partie est prévue pour environ 30 à 40 minutes maximum selon ton rythme.'],
 ['🖱️ COMMANDES','Clique sur une carte OU glisse-la vers le récepteur. Les deux méthodes sont équivalentes. Un clavier peut aussi activer les cartes avec Entrée ou Espace.'],
 ['🔧 STRUCTURE','Chaque atelier comporte un briefing, une simulation manipulable, puis trois questions. Trois tentatives sont permises ; ensuite, le jeu montre et explique la bonne réponse.'],
 ['🏆 PROGRESSION','Tu gagnes de l’expérience (XP), débloques les ateliers, améliores cinq jauges de maîtrise et accumules six trophées. Le boss final est plus exigeant.'],
 ['🧠 PATRONS','Factory : un objet demandé. Abstract Factory : famille d’objets compatibles. Builder : étapes de construction. Prototype : clonage. Singleton : instance unique.'],
 ['🔒 VIE PRIVÉE','Aucun compte, aucune sauvegarde, aucun son, aucune bibliothèque distante, aucune connexion réseau. Fermer ou actualiser la page réinitialise la partie.']
];
function renderModal(){const root=$('#modal-root');if(!state.modal){root.innerHTML='';return;}const p=state.screen==='world'?BY_ID[state.active]:null;root.innerHTML=`<div class="modal-mask" data-action="closeGuide"><section class="guide-modal" role="dialog" aria-modal="true" aria-labelledby="guide-title"><div class="guide-head"><div><span class="eyebrow">// MANUEL DE L'ACADÉMIE</span><h2 id="guide-title">GUIDE DE MISSION</h2></div><button data-action="closeGuide" class="close-modal" aria-label="Fermer le guide">✕</button></div>${p?`<div class="guide-focus"><strong>${p.icon} RAPPEL — ${escapeHTML(p.name)}</strong><p>${escapeHTML(p.idea)}</p><p><b>Quand l'utiliser :</b> ${escapeHTML(p.when)}</p><p><b>Attention :</b> ${escapeHTML(p.trap)}</p></div>`:''}<div class="guide-list">${GUIDE_SECTIONS.map(([head,body])=>`<div><strong>${head}</strong><p>${body}</p></div>`).join('')}</div><div class="guide-footer"><button class="btn-primary" data-action="closeGuide">COMPRIS ✓</button></div></section></div>`;}
function restartAll(){resetTransient();state.screen='home';state.active=null;state.xp=0;state.completed.clear();state.trophies.clear();state.mastery=Object.fromEntries(PATTERNS.map(p=>[p.id,0]));state.runs={};state.calibrationIndex=0;state.calibrationDone=false;state.bossIndex=0;state.bossSolved=0;state.bossDone=false;state.modal=false;render();}
function act(kind){if(kind==='start')return startGame();if(kind==='workshop')return beginWorkshop();if(kind==='nextWorld'){const index=PATTERNS.findIndex(p=>p.id===state.active);if(PATTERNS[index+1])return enterWorld(PATTERNS[index+1].id);}if(kind==='final')return launchBoss();if(kind==='beginBoss')return beginBoss();if(kind==='restart')return restartAll();if(kind==='replayWorld')return enterWorld(state.active,true);if(kind==='guide'||kind==='help'){state.modal=true;renderModal();return;}if(kind==='closeGuide'){state.modal=false;renderModal();return;}}
function navigate(id){if(id==='home')return openHome();if(id==='map')return openMap();if(id==='boss')return launchBoss();if(BY_ID[id])return enterWorld(id);}
function submit(value){if(state.modal||state.busy)return;if(state.screen==='calibration')return resolveCalibration(value);if(state.screen==='world'){const run=state.runs[state.active];if(run.phase==='workshop')return answerWorkshop(value);if(run.phase==='quiz')return answerQuiz(value);}if(state.screen==='boss')return answerBoss(value);}
document.addEventListener('click',event=>{if(event.target.classList.contains('modal-mask')){act('closeGuide');return;}const btn=event.target.closest('button');if(!btn)return;if(btn.id==='brand-home')return openHome();if(btn.id==='open-guide')return act('guide');if(btn.dataset.action){act(btn.dataset.action);return;}if(btn.dataset.nav){navigate(btn.dataset.nav);return;}if(btn.dataset.select){submit(decodeURIComponent(btn.dataset.select));}});
document.addEventListener('dragstart',event=>{const el=event.target.closest('[data-select]');if(!el||state.busy)return event.preventDefault();state.dragValue=decodeURIComponent(el.dataset.select);event.dataTransfer.setData('text/plain',state.dragValue);event.dataTransfer.effectAllowed='copy';el.classList.add('dragging');});
document.addEventListener('dragend',event=>{const el=event.target.closest('[data-select]');if(el)el.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drag-over'));});
document.addEventListener('dragover',event=>{const target=event.target.closest('.drop-target');if(!target||state.busy)return;event.preventDefault();event.dataTransfer.dropEffect='copy';target.classList.add('drag-over');});
document.addEventListener('dragleave',event=>{const target=event.target.closest('.drop-target');if(target&&!target.contains(event.relatedTarget))target.classList.remove('drag-over');});
document.addEventListener('drop',event=>{const target=event.target.closest('.drop-target');if(!target)return;event.preventDefault();target.classList.remove('drag-over');const value=event.dataTransfer.getData('text/plain')||state.dragValue;state.dragValue=null;if(value)submit(value);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal){act('closeGuide');}});
render();
